#include <algorithm>
#include <iostream>

int main() {
    int data[] = {10, 20, 30, 40, 50};
    const size_t N = sizeof(data) / sizeof(int);

    // Raw pointers act as RA iterators
    int* begin_ptr = data;
    int* end_ptr = data + N; // Correct 'one past the end'

    // O(1) random access
    std::cout << "Element at index 2: " << begin_ptr[2] << '\n';

    // Use std::sort (requires Random Access Iterators)
    std::reverse(begin_ptr, end_ptr);
    // Output: 50 40 30 20 10
}
